import{_ as n,l as i,o as l,c as s,v as d,p as c,x as t,d as r,i as m,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"梯度范数监控","description":"","frontmatter":{"title":"梯度范数监控","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grad-norm-monitoring.md","filePath":"llm/grad-norm-monitoring.md","lastUpdated":1789023840000}'),E={name:"llm/grad-norm-monitoring.md"};function h(g,a,u,_,A,B){const o=i("Mermaid");return l(),s("div",null,[a[1]||(a[1]=d('<h1 id="梯度范数监控" tabindex="-1">梯度范数监控 <a class="header-anchor" href="#梯度范数监控" aria-label="Permalink to &quot;梯度范数监控&quot;">​</a></h1><div class="epigraph"><p>全局 $\\ell_2$ 范数把一次反传收成单个标量；它能告诉你这一脚有多重，但不能告诉你重量来自哪一层、哪一种饱和。</p><footer>—— 裁剪前史见 Pascanu, Mikolov &amp; Bengio, ICML 2013；大模型配方中的全局裁剪见 PaLM / Llama 一类报告</footer></div><p><a href="/llm/output-logit-divergence">上一课</a>把输出 LSE 当成传感器。缺口是：有些爆炸先出现在梯度上，logits 还没 Inf——坏 batch、某层 Jacobian 瞬间放大、或流水线某段的局部范数没做 All-Reduce。主干 <a href="/llm/grad-clip-loss-spike">梯度裁剪</a> 已写 \\(\\min(1,c/\\|g\\|_2)\\) 的几何，本课不重推。要补的是<strong>监控怎么布</strong>：记什么、在裁剪前后各看一次、如何与分片并行对齐。后课的激活漂移默认你会这条时间序列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Pascanu 等人在 RNN 里把爆炸写成沿时间的连乘；Transformer 有残差公路，爆炸改成「个别 token / 个别层的局部极大」。全局范数把所有参数的梯度拼成一条向量再取 \\(\\ell_2\\)。它被裁剪之后，日志若只打裁剪后的值，会永远等于 \\(c\\)，信息量为零。必须打<strong>裁剪前</strong>范数：分布、对 \\(c\\) 的触顶率、以及是否伴随 CE 尖峰。</p><p>分片使问题变脏。ZeRO-3 下每个 rank 只有一部分参数，局部 \\(\\|g_{\\mathrm{shard}}\\|_2\\) 不是全局范数；正确做法是 All-Reduce \\(\\sum\\|g_{\\mathrm{shard}}\\|^2\\) 再开方。各自按 \\(c\\) 裁，等于把阈值放大约 \\(\\sqrt{N_{\\mathrm{shard}}}\\)。流水线各段同理。配置写 <code>clip=1.0</code> 却在分片上裁，复现别人的曲线会失败。</p><p><span class="marginnote">「梯度范数」还要声明含不含嵌入、含不含 lm_head。嵌入表大、梯度稀疏，常常主导全局 \\(\\ell_2\\)。只看一个数，会把嵌入的一次热 token 误判成「整网爆炸」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步（或每 \\(k\\) 步）记录：</p><ol><li>全局预裁剪 \\(\\|g\\|_2\\)（跨 rank 归约后）。</li><li>触顶率：\\(\\|g\\|_2\\gt c\\) 的 step 比例，滑动窗口。</li><li>分层范数：嵌入、每层 attn/FFN、输出头，至少这三桶。</li><li>与 CE、LSE、注意力 row-max 对齐的同一 step id。</li></ol><p>分层范数用各桶自己的 \\(\\ell_2\\)，不要把桶平均后再比——维度不同。若嵌入桶单独高、其余正常，对策是嵌入学习率或坏 token，而不是把全局 \\(c\\) 从 1 改到 0.1 把整网更新掐死。</p><p>与 <a href="/llm/autograd-graph">自动微分</a> 的接口：<code>detach</code> 会让某桶范数恒为 0，这是图断了，不是训练稳了。新增损失项（z-loss、MoE 均衡）会改变全局范数的基线，换配方后 \\(c\\) 要重看触顶率，不要沿用旧阈值当神圣。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>裁剪保方向、改幅度。触顶时有效学习率变成 \\(\\eta\\cdot c/\\|g\\|\\)，对全体参数一视同仁。于是：经常触顶 ≈ 你写的 \\(\\eta\\) 从未真正用上，μP 扫到的学习率作废；从不触顶 ≈ \\(c\\) 太松，挡不住下一步的 Inf。健康的预训练允许<strong>偶发</strong>触顶（坏 batch、长尾），不允许<strong>持续</strong>贴顶。持续贴顶时，应先查分层：注意力层范数先飞，回到 logit 增长；输出头先飞，回到 LSE；全体一起飞，才是 \\(\\eta\\) 或精度问题。</p><p>Adam 在裁剪之前还是之后，必须与要对齐的论文一致。先 Adam 再按更新向量裁，统计对象变了，本课的「梯度范数」就不再是 \\(g\\) 而是 \\(\\Delta\\theta\\)。日志名不要都叫 <code>grad_norm</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把监控做成自动 skip 规则；skip 在主干。也不用梯度范数去估计 Hessian 或临界 batch——那是缩放单元的梯度噪声尺度，需要方差而不是 \\(\\ell_2\\) 范数。下一课看激活（前向）尺度漂移：它可以在梯度范数仍正常时发生，因为 LN 把进 \\(F\\) 的分支钉住，主干仍在涨。</p>',17)),(l(),c(p,null,{default:t(()=>[m(o,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20VJP%5B%22%E5%8F%8D%E4%BC%A0%E5%BE%97%E5%88%B0%20g%22%5D%20--%3E%20PRE%5B%22%E9%A2%84%E8%A3%81%E5%89%AA%E5%85%A8%E5%B1%80%E8%8C%83%E6%95%B0%22%5D%0A%20%20PRE%20--%3E%20CLIP%7B%22%E5%A4%A7%E4%BA%8E%20c%3F%22%7D%0A%20%20CLIP%20--%3E%7C%22%E6%98%AF%22%7C%20SCL%5B%22%E6%8C%89%E6%AF%94%E4%BE%8B%E7%BC%A9%E5%9B%9E%22%5D%0A%20%20CLIP%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E5%8E%9F%E6%A0%B7%22%5D%0A%20%20PRE%20--%3E%20LOG%5B%22%E5%88%86%E5%B1%82%E6%A1%B6%E4%B8%8E%E8%A7%A6%E9%A1%B6%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"打裁剪前的全局范数与触顶率；裁剪后贴 \\(c\\) 的数没有诊断价值。"),e("li",null,"分片必须先归约平方和；分层桶区分嵌入、层、输出头。"),e("li",null,"持续贴顶使名义 \\(\\eta\\) 作废；偶发触顶可接受。"),e("li",null,"范数 0 可能是图断开；换损失项后 \\(c\\) 要重校准。"),e("li",null,"出处：Pascanu et al., ICML 2013；PaLM / Llama 配方中的全局裁剪实践。")],-1))])}const k=n(E,[["render",h]]);export{P as __pageData,k as default};
